entries[211363] = { ["name"] = "Rose der erfüllten Träume", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Alle Werte 168 Stunden lang um 10% erhöht. Funktioniert nicht in Schlachtzügen, Dungeons oder anderen Instanzen.\n80 ( 80)\nBenötigt Liebe liegt in der Luft\n\"Manche behaupten, eine Rose symbolisiere das wahre Verlangen. Mit der blauen Rose wird endloses Glück gefeiert. All Eure Wünsche sind bereits in Erfüllung gegangen.\"" }
entries[211364] = { ["name"] = "Rose der Tragödie", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Alle Werte 168 Stunden lang um 10% erhöht. Funktioniert nicht in Schlachtzügen, Dungeons oder anderen Instanzen.\n80 ( 80)\nBenötigt Liebe liegt in der Luft\n\"Manche behaupten, eine Rose symbolisiere wahre Gefühle. Die schwarze Rose steht für Trauer oder Trennung.\"" }
entries[211366] = { ["name"] = "Mondwassertropfen", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Gewährt 750 Ruf bei den Traumwächtern. (2 Sek. Abklingzeit)" }
