entries[211370] = { ["name"] = "Zweig von Gracus", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Gewährt 750 Ruf bei den Traumwächtern. (2 Sek. Abklingzeit)\n\"Fort, aber nicht vergessen\"" }
