entries[211372] = { ["name"] = "Q'onzus Trostpreis", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Gewährt 1 Ruf bei den Traumwächtern. (2 Sek. Abklingzeit)\n\"Beantwortet nächstes Mal eintausend!\"" }
entries[211373] = { ["name"] = "Tasche der vielen Wunder", ["text"] = "Wird beim Aufheben gebunden\n\"Eine Belohnung für jene, die Q'onzus hundert Fragen beantworten können.\"\n<Zum Öffnen rechtsklicken>" }
