entries[211375] = { ["name"] = "Ewig glühende Glut", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n80 ( 80)\n\"Die pure Hitze, die von diesem Kern ausstrahlt, ist fast unerträglich.\"" }
entries[211376] = { ["name"] = "Saatblüte", ["text"] = "Wird beim Aufheben gebunden\n\"Die Blüte einer Pflanze, die mit der Lebensblütenessenz erfüllt wurden. Diese seltenen Knospen besitzen mächtige ästhetische und belebende Eigenschaften.Wird verwendet, um Gegenstände von Talisa Flüsterblüte im Zentrallager zu kaufen.\"" }
