entries[211394] = { ["name"] = "Geerntete Traumsaattruhe", ["text"] = "Wird beim Aufheben gebunden\n\"Enthält Flugsteine, Blühende Schätze und Vorräte der Dracheninseln\"\n<Zum Öffnen rechtsklicken>" }
entries[211395] = { ["name"] = "Aschphodill-Forschungsnotizen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Das leicht versengte Pergament ist voller Beobachtungsnotizen und Tintenflecken.\"\n<Zum Lesen rechtsklicken>\nVerkaufspreis:" }
entries[211396] = { ["name"] = "Eingestimmter Leuchtsporengriff", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Stimmt Euch vollständig auf diesen Gegenstand ein und erhaltet den symbiotischen Leuchtsporengriff.\n\"Ein symbiotischer Leuchtsporengriff, bereit, auf Fyr'alath eingestimmt zu werden.\"" }
entries[211397] = { ["name"] = "Eingestimmte Rune der Schattenbindung", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Stimmt Euch vollständig auf diesen Gegenstand ein und erhaltet die Rune der Schattenbindung.\n\"Eine machtvolle Rune, die stärker wird, wenn man sie beschädigt. In Zusammenarbeit mit Inschriftenmeisterin Lydiara gefertigt.\"" }
entries[211398] = { ["name"] = "Eingestimmtes weises Pergament", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Stimmt Euch vollständig auf diesen Gegenstand ein und erhaltet das konzentrierte weise Pergament.\n\"Auf diesem Pergament werden Zauberformeln beschrieben, die Schattenflamme vom Träger fortleiten können. In Zusammenarbeit mit Meisterverzauberin Shalasar gefertigt.\"" }
entries[211399] = { ["name"] = "Technik: Glyphe des Lunarchamäleons", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man eine Glyphe des Lunarchamäleons herstellt.\nBenötigt Inschriftenkunde der Dracheninseln (1)\nVerkaufspreis:" }
entries[211400] = { ["name"] = "Glyphe des Lunarchamäleons", ["text"] = "Klassen: Druide\nBenutzen: Lehrt Euch permanent diese Glyphe.\n\nJedes Mal, wenn Ihr Mondkingestalt annehmt, wird Eure verwandelte Gestalt zufällig bestimmt.\nVerkaufspreis:" }
