entries[211446] = { ["name"] = "Ensemble: Erbe der Dunkelspeere", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Sammelt die Vorlagen der Traditionsrüstung der Dunkelspeere. Dies beinhaltet folgende Sets: Pakt der Dunkelspeere und Loyalität der Dunkelspeere sowie zwei Masken von mit den Dunkelspeeren verbündeten Loa. Diese Vorlagen können nur von Dunkelspeertrollen getragen werden." }
