entries[211474] = { ["name"] = "Schattenblinder Barsch", ["text"] = "Benutzen: Wenn Ihr das nicht essen wollt, dann werft es einem Frosch zu.\n\"Ein seltsam saurer Fisch, aber die Frösche lieben sie!\"\nVerkaufspreis:" }
