entries[211481] = { ["name"] = "Stampferstiefel", ["text"] = "\"Die Maschinenflüsterer stellen Schuhe her, mit denen gewaltig aufgestampft werden kann, was (manche) Maschinen erneut aktiviert.\"" }
entries[211483] = { ["name"] = "Rasende Sandkugel", ["text"] = "Questgegenstand\nBenutzen: Zerquetscht die Sandkugeln und die Wasserkugeln, um elementargeladenen Schlick zu erzeugen." }
entries[211484] = { ["name"] = "Rasende Wasserkugel", ["text"] = "Questgegenstand\nBenutzen: Zerquetscht die Sandkugeln und die Wasserkugeln, um elementargeladenen Schlick zu erzeugen." }
entries[211485] = { ["name"] = "Elementargeladener Schlick", ["text"] = "Questgegenstand\n\"Schwache Energie strömt durch den Schlick.\"" }
entries[211486] = { ["name"] = "Schlängelnder Kriecherdrache", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Das ist ein Reitdrache.\nBeschwört einen reitbaren schlängelnden Kriecherdrachen oder gibt ihn wieder frei.\n\nBei diesem Reittier kann 'Mitreiten' verwendet werden.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Diese Drachen fühlen sich in den Tiefen der Erde und den Weiten des Himmels zuhause.\"\nErfolg:\nEine schlangenhafte Entdeckung" }
entries[211489] = { ["name"] = "Riesengroßer Tropfen Feuerhonig", ["text"] = "Questgegenstand\n\"Dieser riesengroße Tropfen Feuerhonig ist zwar nicht raffiniert, aber unglaublich heiß!\"" }
entries[211493] = { ["name"] = "Brax' Messingschlagring", ["text"] = "Questgegenstand\n\"Lindert die Hiebe von irdenen Händen. Bei anderen eher nicht.\"" }
entries[211494] = { ["name"] = "Funke der Anfänge", ["text"] = "Wird an Kriegsmeute gebunden\nOptionales Handwerksmaterial\n\nGewährt die folgende Eigenschaft: Legt die Startgegenstandsstufe je nach Fertigungsqualität (564-577) fest und markiert den Gegenstand als 'Anfänger gefertigt'.\n\"Dieses einzigartige Herstellungsmaterial kann Eurer Kriegsmeute dabei helfen, ihre Reise in Khaz Algar zu beginnen.\"" }
entries[211495] = { ["name"] = "Traumgebundene Verstärkungsrune", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Erhöht die Beweglichkeit, Intelligenz und Stärke für 1 Stunde um 87 . Verstärkungsrune. (1 Min Abklingzeit)\nBenötigt Ruhmrang 18 bei den Traumwächtern.\n\"Die Stärke des Traums in einem kraftvollen Nebel verdichtet.\"\nVerkaufspreis:" }
entries[211513] = { ["name"] = "Heulende Echos", ["text"] = "Wird beim Aufheben gebunden\nZweihändig Stangenwaffe\n127 - 236 Schaden Geschwindigkeit 3.60\n(50.4 Schaden pro Sekunde)\n+67 Beweglichkeit\n+100 Ausdauer\nErhöht Eure kritische Trefferwertung um + 78.\nErhöht Eure Tempowertung um + 55.\nHaltbarkeit 120 / 120\nVerkaufspreis:" }
entries[211515] = { ["name"] = "Gesplitterter Funke der Erweckung", ["text"] = "Saison 4 von Dragonflight\nWird beim Aufheben gebunden\nBenutzen: Kombiniert 2 gesplitterte Funken der Erweckung, um einen Funken der Erweckung herzustellen.\nHandwerksmaterial\n\"Ein Bruchstück eines Funkens der Erweckung, dessen Kräfte wiederhergestellt werden können, wenn die Teile gesammelt werden.\"\nVerkaufspreis:" }
entries[211516] = { ["name"] = "Funke der Erweckung", ["text"] = "Saison 4 von Dragonflight\nWird beim Aufheben gebunden\nOptionales Handwerksmaterial\n\nGewährt die folgende Eigenschaft: Legt Startgegenstandsstufe nach Fertigungsqualität (489-502) fest, markiert als 'Erwecktgefertigt'.\n\"Ein mächtiger Funke, der von der Erweckung der Dracheninseln beeinflusst wurde. Durch dieses einzigartige Handwerksmaterial kann ein Gegenstand Wissen verleihen, das jenseits der Fähigkeiten des sterblichen Verstands ist.\"\nVerkaufspreis:" }
entries[211518] = { ["name"] = "Erwecktes Wappen des verzauberten Wyrms", ["text"] = "Wird beim Aufheben gebunden\nOptionales Handwerksmaterial\n+30 Rezeptschwierigkeit\nBenutzbar mit: Rezepte der Dracheninseln für epische Ausrüstungsteile, die mit einem Funken der Erweckung hergestellt werden.\n\"Ein mächtiges Reagenz, das von Verzauberern erschaffen wurde.\"\nVerkaufspreis:" }
