entries[211775] = { ["name"] = "Ausgebleichte Knochen", ["text"] = "Questgegenstand\n\"Zum Glück scheint keiner davon menschlich zu sein. Er ist unwahrscheinlich, dass Anduin hier sein Ende gefunden hat.\"" }
entries[211776] = { ["name"] = "Durchnässtes Reparaturset", ["text"] = "Tak-Rethan-Abgrund\n\"Die Wahrscheinlichkeit ist groß, dass dieses Reparaturset schon früher nicht viel geholfen hat. Wie viel schlimmer kann es also ein Wasserschaden machen?\"" }
