entries[211783] = { ["name"] = "Reste von abgenutztem Stoff", ["text"] = "Questgegenstand\nEinzigartig (5)\n\"Es sind nur noch Reste übrig, aber die ausgefransten Fäden des Stoffs kommen Euch bekannt vor.\"" }
