entries[211810] = { ["name"] = "Knabberlis mit Schokoladenüberzug", ["text"] = "Benutzen: Stellt im Verlauf von 30 Sek. ( 175 * 30 / 5) Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben.\n\"Mit seltsam herzhaftem Kern.\"\nVerkaufspreis:" }
entries[211811] = { ["name"] = "Kleiner Tropfen Feuerhonig", ["text"] = "Questgegenstand\n\"Der Feuerhonig ist viel zu heiß, als dass Ihr ihn mit bloßen Händen anfassen könntet. Glücklicherweise habt Ihr ein Glas!\"" }
entries[211812] = { ["name"] = "Erneuerter Protodrache: Liebesrüstung", ["text"] = "Drachenwächtermanuskript\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Schaltet diese Anpassungsoption für den erneuerten Protodrachen frei, wenn der Gegenstand in der Nähe des Podiums der Transformation benutzt wird." }
entries[211858] = { ["name"] = "Elektrifizierte Mooswolle", ["text"] = "Questgegenstand\n\"Das raue Moos knistert vor gespeicherter elektrischer Energie.\"" }
entries[211861] = { ["name"] = "Umbralaubergine", ["text"] = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\n\"Ein seltenes und ungewöhnliches Gewächs.\"" }
entries[211862] = { ["name"] = "Überlassene Ottukvorhut", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Ein Geschenk von Brena. Die Iskaaraner sandten ihre loyalsten (und niedlichsten) Begleiter, um über Kalecgos und seine wiedervereinte Familie in Valdrakken zu wachen.\"\nErfolg:\nKampfclub\nKategorie:\nErkundung" }
entries[211863] = { ["name"] = "Zischender Magmakern", ["text"] = "Questgegenstand\nEinzigartig\n\"Wenn man sie formt und schnitzt, können diese gefährlich heißen Kerne eine schöne Dekoration ergeben.\"" }
entries[211864] = { ["name"] = "Exquisites Liebesboot", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Beschwört Euer exquisites Liebesboot auf der Wasseroberfläche innerhalb von 20 Metern.\nWährend 'Liebe liegt in der Luft' aktiv ist, ist die Abklingzeit verringert. (30 Min Abklingzeit)\n\"Feiert die Liebe mit diesem eleganten Wassergefährt für bis zu vier Personen.\"" }
entries[211865] = { ["name"] = "Zahnradkauers Schlüssel", ["text"] = "Questgegenstand\n\"Eine Sammlung von erbeuteten Schlüsseln der Irdenen. Leicht angekaut.\"" }
entries[211868] = { ["name"] = "Schlängelnder Kriecherdrache: Mondfestrüstung", ["text"] = "Drachenwächtermanuskript\nWird beim Aufheben gebunden\nEinzigartig\nBenutzen: Schaltet diese Anpassungsoption für den schlängelnden Kriecherdrachen frei, wenn der Gegenstand in der Nähe des Podiums der Transformation benutzt wird.\n\"Eine Schriftrolle, die einen mächtigen Protodrachen mit leuchtend grünen Schuppen beschreibt.\"" }
entries[211869] = { ["name"] = "Standarte der drakonischen Legende", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Repräsentiert Euren Saisonerfolg mit einem Banner. (2 Min Abklingzeit)" }
entries[211870] = { ["name"] = "Finns Klingen", ["text"] = "Questgegenstand\n\"Ein Paar vom Meer verwitterte Klingen.\"" }
entries[211872] = { ["name"] = "Patrouillenfackel", ["text"] = "Questgegenstand\nBenutzen: Zeigt die Patrouillenfackel, enthüllt so in der Dunkelheit verborgene Gegenstände und fügt bis zu 4 Gegnern in der Nähe 1 Heiligschaden zu. (6 Sek. Abklingzeit)\n\"Ihr Schein schenkt den Arathi Hoffnung und flößt anderen Furcht ein.\"" }
entries[211873] = { ["name"] = "Zügel des gilnearischen Streuners", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört Euren gilnearischen Streuner oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Eine skrupellose Gattung Streuner, deren Wildheit sonst nur von den Worgen erreicht wird. Diese entschlossenen Kreaturen verkörpern Disziplin und eine gezügelte Grausamkeit, die selbst von den Worgen bewundert wird.\"\nQuest:\nEin neuer Morgen bricht an\nZone:\nGilneas" }
