entries[211945] = { ["name"] = "Fackel der Heiligen Flamme", ["text"] = "Questgegenstand\nBenutzen: Wirft eine Fackel mit einer heiligen Flamme, die jeden Käfig der Kobyss verbrennt, den sie trifft.\n\"Brennt mit der Heiligen Flamme von Arathor.\"" }
entries[211946] = { ["name"] = "Hearthstone-Spieltisch", ["text"] = "Spielzeug\nBenutzen: Platziert einen Hearthstone-Spieltisch und spielt gegen einen würdigen Gegner! (20 Min Abklingzeit)" }
entries[211947] = { ["name"] = "Erntesamenvorrat", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Pflanzt die Erntesamen in samentaugliche Erde ein.\n\"Samen, die eingepflanzt werden können.\"" }
entries[211948] = { ["name"] = "Speer der Kobyss", ["text"] = "Questgegenstand\n\"Tötet Kobyss genau wie Arathi.\"" }
entries[211949] = { ["name"] = "Durumus Glaspupille", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Werft mich!\nVerkaufspreis:" }
entries[211950] = { ["name"] = "Lebhafte Tasche mit erweckten Wappen des Wyrms", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Sammelt 15 erweckte Wappen des Wyrms.\nIhr könnt gerade keine 15 erweckten Wappen des Wyrms verdienen." }
entries[211951] = { ["name"] = "Tasche mit erweckten Wappen des Welpen", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Sammelt 15 erweckte Wappen des Welpen. Diese Wappen ignorieren das Saisonlimit.\nSchließt die Quest \"Wappentraum\" von Vaskarn im Zentrallager ab, um Eure Traumwappen abwerten zu können.\nIhr müsst die Quest \"Erweckte Wappen, unbegrenzte Möglichkeiten\" von Vaskarn in Valdrakken abschließen, um Erweckte Wappen abzuwerten." }
entries[211952] = { ["name"] = "Beutel mit erweckten Wappen des Drachen", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Sammelt 15 erweckte Wappen des Drachen. Diese Wappen ignorieren das Saisonlimit.\nSchließt die Quest \"Wappentraum\" von Vaskarn im Zentrallager ab, um Eure Traumwappen abwerten zu können.\nIhr müsst die Quest \"Erweckte Wappen, unbegrenzte Möglichkeiten\" von Vaskarn in Valdrakken abschließen, um Erweckte Wappen abzuwerten." }
entries[211958] = { ["name"] = "Sorgfältige Experimente", ["text"] = "\"Experimentiert mit instabilen Reagenzien in der Hoffnung, neue Rezepte zu entdecken.\"" }
entries[211959] = { ["name"] = "Verlorene Habseligkeiten", ["text"] = "Questgegenstand\n\"Eine Sammlung an Gegenständen, die früher Andari gehörten, einem Lampenanzünder, der im Dienst fiel.\"" }
entries[211960] = { ["name"] = "Spielfigur", ["text"] = "Questgegenstand" }
entries[211961] = { ["name"] = "Raketengetriebener Schlagschrauber", ["text"] = "Questgegenstand\n\"Viel zu kompliziert, ist aber mit einer standardmäßigen Goblinindustrieeinsatz ausgestattet. Teil eines Sets.\"" }
entries[211962] = { ["name"] = "Glitzerndes Erz", ["text"] = "Questgegenstand\n\"Rubinrote Streifen schimmern durch das Gestein. Dieses Erz ist perfekt für Veredelung durch Irdene.\"" }
entries[211963] = { ["name"] = "Deckenfeger", ["text"] = "Questgegenstand\nBenutzen: Feuert eine einzelne Kanonenkugel ab, die bei Kontakt explodiert. (8 Sek. Abklingzeit)" }
entries[211964] = { ["name"] = "Stillsteinfang", ["text"] = "Questgegenstand\n\"Enthält eine Auswahl an im Stillsteintümpel gefangenen Fischen.\"" }
