entries[211966] = { ["name"] = "Versiegelte Kiste der Neruber", ["text"] = "Questgegenstand\n\"Geheimnisvolle Kiste, wirkt wie nicht aus diesen Landen.\"" }
entries[211967] = { ["name"] = "Große versiegelte Kiste", ["text"] = "Questgegenstand\n\"Große Kiste voller verloren geglaubter Dinge.\"" }
entries[211968] = { ["name"] = "Bauplanbündel", ["text"] = "Questgegenstand\n\"Fehlende Bauzeichnungen und -pläne.\"" }
entries[211969] = { ["name"] = "Verschlossene Arathitruhe", ["text"] = "Questgegenstand\n\"Dicke Schlösser schützen die Wertgegenstände im Inneren.\"" }
entries[211970] = { ["name"] = "Erntewein", ["text"] = "Questgegenstand\n\"Aus Früchten aus Heilsturz gekeltert.\"" }
entries[211971] = { ["name"] = "Gelbbrauner Mais", ["text"] = "Questgegenstand\n\"Geerntet im Licht eines Schlüsselsteins.\"" }
entries[211972] = { ["name"] = "Landwirtschaftliche Vorräte von Heilsturz", ["text"] = "Questgegenstand\n\"Verschiedene Werkzeuge, Dünger und Samen.\"" }
entries[211973] = { ["name"] = "Spinnenberührter Beutel", ["text"] = "Questgegenstand\n\"Beutel mit verloren geglaubten Dingen, mit Spinnweben versiegelt.\"" }
entries[211974] = { ["name"] = "Aufgerollter Arathiteppich", ["text"] = "Questgegenstand\n\"Jemandem fehlt ein Teppich.\"" }
entries[211975] = { ["name"] = "Arathiwerkzeugsatz", ["text"] = "Questgegenstand\n\"Kleine Kiste mit fehlenden landwirtschaftlichen Werkzeugen.\"" }
