entries[212218] = { ["name"] = "Ensemble: Schattenbannornat des Schreckenslords", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Sammelt die Vorlagen des Schattenbannornats des Schreckenslords.\n\"Hütet Euch vor den tiefen Schatten, denn die Schreckenslords sind ihre Gebieter.\"" }
entries[212219] = { ["name"] = "Ensemble: Giftbannornat des Schreckenslords", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Sammelt die Vorlagen des Giftbannornats des Schreckenslords.\n\"Wie eine Viper aus den Schatten entziehen sich auch Schreckenslords oft der Sicht, bis sie zuschlagen.\"" }
entries[212220] = { ["name"] = "Ensemble: Gewand der Liebeshexe", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Sammelt die Vorlagen des Gewands der Liebeshexe.\n\"Ein plötzlicher Ausbruch von Liebe und Freude hat Gerüchte darüber entfacht, dass dieser mysteriöse Zirkel wieder in Erscheinung getreten ist.\"" }
entries[212221] = { ["name"] = "Ensemble: Gewand der Himmelshexe", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Sammelt die Vorlagen des Gewands der Himmelshexe." }
entries[212222] = { ["name"] = "Ensemble: Gewand der Zwielichthexe", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Sammelt die Vorlagen des Gewands des Zwielichthexe.\n\"Manchen steht eine düstere Erscheinung einfach besser, und diese Hexen sind davon überzeugt, dass jeder sein eigenes Glück in die Hand nehmen sollte.\"" }
entries[212223] = { ["name"] = "Elementaressenz", ["text"] = "Questgegenstand" }
entries[212224] = { ["name"] = "Relikte der Titanen", ["text"] = "Questgegenstand\n\"Das unerkennbare Relikt ist von Rost durchzogen und wurde durch Zeit und Sand schwer beschädigt und gebrochen.\"" }
entries[212227] = { ["name"] = "Zügel des ausgefuchsten Freundchens", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört das ausgefuchste Freundchen als Reittier und gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Diese magischen Kreaturen gedeihen durch Liebe und Freundschaft.\"\nHandelsposten" }
entries[212228] = { ["name"] = "Zügel des gleitenden Himmelsfuchses", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört den gleitenden Himmelsfuchs als Reittier und gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Steigt mit dem treusten und liebevollsten Fuchs in ganz Azeroth in die Lüfte.\"\nWoW-Shop" }
entries[212229] = { ["name"] = "Zügel des Zwielichthimmelsstreuners", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört den Zwielichthimmelsstreuner als Reittier und gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Er wird von einigen auch als Mitternachtstrickser bezeichnet und viele Paare glauben, dass er dafür verantwortlich ist, dass sich ihre Wege in der Nacht gekreuzt haben.\"" }
entries[212289] = { ["name"] = "Boshaftes Fläschchen der klassischen Geister", ["text"] = "Benutzen: Trinkt dies, um Eure Manaregeneration um 8% zu erhöhen, wenn Ihr 5 Sek. lang keinen hilfreichen Zauber gewirkt habt, der Mana kostet.\n\nErhaltene Ehre ist um 15% erhöht.\n\nHält 1 Stunde lang und über den Tod hinaus an. Die Benutzung eines identischen Fläschchens verlängert die Dauer um 1 Stunde\nVerkaufspreis:" }
entries[212292] = { ["name"] = "Boshaftes Fläschchen der Ehre", ["text"] = "Benutzen: Trinkt dies, um Eure erhaltene Ehre um 15% zu erhöhen. Kann in allen gewerteten und ungewerteten PvP-Umgebungen eingesetzt werden.\n\nHält 1 Stunde lang und über den Tod hinaus an. Die Benutzung eines identischen Fläschchens verlängert die Dauer um 1 Stunde\nVerkaufspreis:" }
entries[212295] = { ["name"] = "Boshaftes Fläschchen des manifestierten Jähzorns", ["text"] = "Benutzen: Bei Eurem Tod manifestiert sich Eure Wut als rasender Elementar, durch den Ihr Euch 10 Sek. lang an Euren Feinden rächen könnt. Kann nur einmal alle 2 Min. auftreten.\n\nErhaltene Ehre ist um 15% erhöht.\n\nHält 1 Stunde lang und über den Tod hinaus an. Die Benutzung eines identischen Fläschchens verlängert die Dauer um 1 Stunde\nVerkaufspreis:" }
entries[212298] = { ["name"] = "Boshaftes Fläschchen der Abrisskugel", ["text"] = "Benutzen: Todesstöße von Spielercharakteren erhöhen 20 Sek. lang Euren verursachten Schaden um 8% und Euren erlittenen Schaden um 4%. Bis zu 5-mal stapelbar. Wenn Ihr getötet werdet, während dieser Effekt aktiv ist, erhält Euer Angreifer einen Teil dieser Macht.\n\nErhaltene Ehre ist um 15% erhöht.\n\nHält 1 Stunde lang und über den Tod hinaus an. Die Benutzung eines identischen Fläschchens verlängert die Dauer um 1 Stunde\nVerkaufspreis:" }
entries[212317] = { ["name"] = "Geborgener Zunderkasten", ["text"] = "Questgegenstand\n\"Damit habt Ihr die heilige Flamme immer bei Euch, egal, wo Ihr seid.\"" }
entries[212329] = { ["name"] = "Luchsleine", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (100)\nBenutzen: Leint einen Luchs an, der sich in der Nähe befindet, damit er Euch vorübergehend im Kampf helfen kann.\n\nVerwendbar in Blüte des Lichts und nahen Schlüsselflammengebieten.\n\"Luchse lieben Abenteuer!\"\nVerkaufspreis:" }
entries[212330] = { ["name"] = "Schattengehärtete Triebfeder", ["text"] = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\n\"Irgendwie existiert diese ungewöhnlich starke Quelle.\"" }
entries[212331] = { ["name"] = "Ein ungewöhnliches Tierchen", ["text"] = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\n\"Eine außergewöhnliche Spinne, die nicht in Heilsturz beheimatet ist.\"" }
entries[212333] = { ["name"] = "Expeditionszunderkasten", ["text"] = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\n\"Zeichen der Hoffnung, das viele der frühen Teilnehmer der Heilsturzexpedition bei sich trugen.\"" }
entries[212334] = { ["name"] = "Anti-Fungus-Feuerbombe", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Wirft eine Feuerbombe, die invasive Sporen verbrennt und zerstört. (3 Sek. Abklingzeit)" }
entries[212335] = { ["name"] = "Reisetasche des Sammlers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n36 Platz Tasche" }
entries[212336] = { ["name"] = "Wappenrock der Taverne", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nWappenrock\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen." }
entries[212337] = { ["name"] = "Herdstein", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Bringt Euch zurück zu Eurem Heimatort: Ruhestein-Ort. Sprecht mit einem Gastwirt an einem anderen Ort, um Euren Heimatort zu ändern." }
entries[212339] = { ["name"] = "Kleiner Beutel mit Samen", ["text"] = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\n\"Diese Samen wirken, als wären sie bereit, zu keimen, wenn sie etwas Licht genießen dürfen.\"" }
entries[212340] = { ["name"] = "Seltsames Gefäß", ["text"] = "Fungusphantasterei\n\"Aus dem Gefäß steigt eine seltsame Substanz auf. Es sollte bei bedächtigem Vorgehen möglich sein, sie Euch zunutze zu machen.\"" }
entries[212341] = { ["name"] = "Doppeltoter Hauer", ["text"] = "\"Der erste Tod ist eine Tragödie. Der zweite Tod ist eine Gnade.\"\nVerkaufspreis:" }
entries[212344] = { ["name"] = "Truhenschlüssel", ["text"] = "Questgegenstand\nEinzigartig" }
entries[212345] = { ["name"] = "Gejagtes Blut der Hakkari", ["text"] = "Verkaufspreis:" }
entries[212346] = { ["name"] = "Fehlgeschlagener Tribut der Gurubashi", ["text"] = "Verkaufspreis:" }
entries[212352] = { ["name"] = "Totem der Mosh'Ogg", ["text"] = "Verkaufspreis:" }
entries[212361] = { ["name"] = "Opportunist", ["text"] = "Tüftleredelstein\nWird beim Aufheben gebunden\nEinzigartig\nAnlegen: Gewährt 4 Sek. lang, nachdem Ihr einen Gegner betäubt habt, eine um 50% erhöhte kritische Trefferchance.\n80 ( 80)\n\"Passt in einen Tüfteleisockel.\"" }
entries[212362] = { ["name"] = "Erblühen des Sonnenwanderers", ["text"] = "Tüftleredelstein\nWird beim Aufheben gebunden\nEinzigartig\nAnlegen: Eure kritischen Treffer brechen in einer feurigen Explosion aus, die Gegnern innerhalb von 15 Metern um Euer Ziel Feuerschaden zufügt.\n80 ( 80)\n\"Passt in einen Tüfteleisockel.\"" }
entries[212365] = { ["name"] = "Eifer", ["text"] = "Tüftleredelstein\nWird beim Aufheben gebunden\nEinzigartig\nAnlegen: Während Ihr mehr als 80% Gesundheit besitzt, verbrauchen Eure Angriffe Gesundheit und verursachen Heiligschaden in Höhe der verbrauchten Menge. (1 Sek. Abklingzeit)\n80 ( 80)\n\"Passt in einen Tüfteleisockel.\"" }
entries[212366] = { ["name"] = "Schneide des Arkanisten", ["text"] = "Tüftleredelstein\nWird beim Aufheben gebunden\nEinzigartig\nAnlegen: Eure Angriffe verbrauchen einen Teil Eures Absorptionsschilds, um Arkanschaden in Höhe der verbrauchten Menge zu verursachen. (10 Sek. Abklingzeit)\n80 ( 80)\n\"Passt in einen Tüfteleisockel.\"" }
entries[212367] = { ["name"] = "Tasche mit erweckten Wappen des Wyrms", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Sammelt 15 erweckte Wappen des Wyrms. Diese Wappen ignorieren das Saisonlimit.\nSchließt die Quest \"Wappentraum\" von Vaskarn im Zentrallager ab, um Eure Traumwappen abwerten zu können.\nIhr müsst die Quest \"Erweckte Wappen, unbegrenzte Möglichkeiten\" von Vaskarn in Valdrakken abschließen, um Erweckte Wappen abzuwerten." }
entries[212369] = { ["name"] = "Schleife der Schlachtfeldliebenden", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nRücken\n\"Wenn der Liebende auch ein Krieger ist.\"\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[212371] = { ["name"] = "Initiationsabzeichen der Archivare von Azeroth", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Ein Abzeichen von Eadweard, das Euren offiziellen Status als Archivar von Azeroth belegt. Tauscht es bei Versorgerin Aristta gegen Eure Kappe des Archivars.\"" }
entries[212372] = { ["name"] = "Magentafarbene Maskeradenhandschuhe", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nHände Kosmetisch\n\"Herrscht nicht mit eisernem Griff, sondern einem samtenen Handschuh.\"\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[212373] = { ["name"] = "Gazemagentagewand", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nBrust Kosmetisch\n\"Macht königliche Bekanntschaft in diesem hauchdünnen Gewand.\"\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[212374] = { ["name"] = "Klassischer rosenroter Wappenrock", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nWappenrock\n\"Ein einfacher Wappenrock für liebevolle Gelegenheiten.\"\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen." }
entries[212375] = { ["name"] = "Herziger rosenroter Langbogen", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nDistanz Bogen\n1 - 2 Schaden Geschwindigkeit 3.00\n(0.5 Schaden pro Sekunde)\n\"Vom guten Namen der Liebe ins Herz getroffen.\"\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[212376] = { ["name"] = "Herziger gotischer Langbogen", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nDistanz Bogen\n1 - 2 Schaden Geschwindigkeit 3.00\n(0.5 Schaden pro Sekunde)\n\"Liebe kann auch wehtun.\"\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[212377] = { ["name"] = "Rosenroter Zauberstab der Liebeshexe", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nDistanz Zauberstab\n1 Schaden Geschwindigkeit 2.00\n(0.5 Schaden pro Sekunde)\n\"Bekämpft das Böse mit der Macht der Liebe.\"\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[212378] = { ["name"] = "Gotisches Szepter der Zwielichthexe", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nDistanz Zauberstab\n1 Schaden Geschwindigkeit 2.00\n(0.5 Schaden pro Sekunde)\n\"Die Dunkelheit möge herrschen.\"\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[212379] = { ["name"] = "Rosenroter Stab der Liebeshexe", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nZweihändig Stab\n1 Schaden Geschwindigkeit 3.60\n(0.3 Schaden pro Sekunde)\n\"Die Liebe findet immer einen Weg.\"\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[212380] = { ["name"] = "Gotischer Stab der Zwielichthexe", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nZweihändig Stab\n1 Schaden Geschwindigkeit 3.60\n(0.3 Schaden pro Sekunde)\n\"Glitzert im Zwielicht.\"\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[212381] = { ["name"] = "Bollwerk der Liebe", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nSchildhand Schild\n14 Rüstung\n\"Liebe ist ein Schlachtfeld.\"\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[212382] = { ["name"] = "Fluoreszierende Spaltklinge", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nZweihändig Schwert\n1 Schaden Geschwindigkeit 3.60\n(0.3 Schaden pro Sekunde)\n\"Obwohl die heiligen Verteidiger von Karabor fielen, blieben ihre kristallenen Waffen unversehrt.\"\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[212383] = { ["name"] = "Gähnender Korb mit erweckten Wappen des Aspekts", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Sammelt 15 erweckte Wappen des Aspekts.\nIhr könnt gerade keine 15 erweckten Wappen des Aspekts verdienen." }
entries[212384] = { ["name"] = "Rastloser Beutel mit erweckten Wappen des Drachen", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Sammelt 15 erweckte Wappen des Drachen.\nIhr könnt gerade keine 15 erweckten Wappen des Drachen verdienen." }
entries[212385] = { ["name"] = "Moiras heilende Woge", ["text"] = "Questgegenstand\n\"Moira heilt den nächsten verletzten Irdenen.\"" }
