entries[212448] = { ["name"] = "Medaillon der verlorenen Erinnerungen", ["text"] = "Wird beim Aufheben gebunden\nHals\n+5.034 Ausdauer\nErhöht Eure kritische Trefferwertung um + 2.596.\nErhöht Eure Tempowertung um + 649.\nVerkaufspreis:" }
entries[212449] = { ["name"] = "Sik'rans endloses Arsenal", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+1.914 [Beweglichkeit oder Stärke]\nAnlegen: Nimmt eine Kampfhaltung basierend auf der zuletzt gezückten Waffe ein.\nBenutzen: Surekisches Gedeihen\nBeschwört zwei Schwerter aus dem Arsenal, um Euer Ziel wild anzugreifen und im Verlauf von 3 Sek. ( 1 * 705278 ) Schattenschaden zuzufügen. Gewährt 338 Parieren und 225 Vermeidung, bis die nächste Waffe gezogen wird. (1 Min Abklingzeit)\nVerkaufspreis:" }
entries[212450] = { ["name"] = "Autorität des Schwarmfürsten", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nErhöht Eure Tempowertung um + 1.001.\nAnlegen: Eure Angriffe und Fähigkeiten haben eine hohe Chance, einen Skarabäus zu beschwören, der ein stärkendes Fleischstück aus Eurem Ziel reißt. Skarabäen verursachen 6915 körperlicher Schaden und verringern Euren erlittenen Schaden um 50% bis 172816 Schaden verhindert wurde.\nBenutzen: Bringt Euren Schwarm zur Raserei und beschwört im Verlauf von 3 Sek. 12 Skarabäen, die Eure Gegner heimsuchen. Die Anzahl der Skarabäen wird durch Euer Tempo erhöht. (1 Min Abklingzeit)\nVerkaufspreis:" }
entries[212451] = { ["name"] = "Anomale Zauberschmiede", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+1.914 Intelligenz\nAnlegen: Sammelt alle 15 Sek. dunkle Macht von der Zauberschmiede, um Euren nächsten Einsatz von [Eurem Spezialisierungszauber] zu ermächtigen, damit er zusätzlich ( 1 * 73672 ) Schattenschaden verursacht.\nBenutzen: Verstärkt die Macht der Zauberschmiede ohne Rücksicht auf Verluste und multipliziert bis zu 5-mal ihren aktuellen Schaden bis kurz nach Verlassen des Kampfes um 125%. Bei maximaler Macht erhaltet Ihr 6 Sek. lang 830 Tempo, wenn Ihr Euren nächsten Einsatz von [Eurem Spezialisierungszauber] ermächtigt.\n\nHütet Euch vor flüchtigen Blicken ins Ungehörige. (1 Min Abklingzeit)\nVerkaufspreis:" }
entries[212452] = { ["name"] = "Grausame Spritze", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nErhöht Eure kritische Trefferwertung um + 1.001.\nAnlegen: Bei Euren Heilzaubern besteht eine hohe Chance, dass Ihr Euch eine Aufladung ' Instabiles Serum ' injiziert. Mehrere Aufladungen können sich überschneiden.\n\nWenn ein Verbündeter unter 70% Gesundheit fällt, stoßt Ihr eine Aufladung aus und heilt ihn um 240979 Gesundheit. Aufladungen, die nach 15 Sek. noch nicht verbraucht wurden, werden katalysiert und gewähren Euch stattdessen 10 Sek. lang 2894 Intelligenz.\nVerkaufspreis:" }
entries[212453] = { ["name"] = "Ätzendes Himmelsschreckenorgan", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+1.914 Stärke\nBenutzen: Bespritzt Euer Ziel mit instabiler Säure, die 20 Sek. lang alle 1 Sek. ( 1 * 7902 ) Naturschaden verursacht.\n\nEure Fähigkeiten verstärken den Schaden der Säure für die verbleibende Dauer pro Sekunde um ( 1 * 7902 ) zusätzlichen Naturschaden, bespritzen bis zu 5 Gegner in der Nähe und fügen ihnen pro Stapel ( 1 * 790 ) Naturschaden zu. (1s Abklingzeit) (2 Min Abklingzeit)\nVerkaufspreis:" }
entries[212454] = { ["name"] = "Mandat der verrückten Königin", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nErhöht Eure kritische Trefferwertung um + 1.001.\nBenutzen: Nehmt, was rechtmäßig Euch gehört und labt Euch an der Essenz Eures Ziels, um ( 1 * 2174283 ) Schattenschaden zu verursachen und Euch im Verlauf von 2 Sek. um 320973 zu heilen. Schaden und Heilung erhöhen sich gemäß der fehlenden Gesundheit des Ziels.\n\nWenn der Effekt das Ziel tötet, wird die Abklingzeit um 60 Sek. reduziert. (2 Min Abklingzeit)\nVerkaufspreis:" }
entries[212455] = { ["name"] = "11.0 Raid Template - Physical DPS - Trinket", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+112 [Beweglichkeit oder Stärke]\nVerkaufspreis:" }
entries[212456] = { ["name"] = "Vertrag des Leerenschnitters", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+1.914 Beweglichkeit\nAnlegen: Eure Fähigkeiten haben eine hohe Chance, ein Phantom zu beschwören, das Eurem Ziel ( 1 * 159051 ) Schattenschaden und allen anderen Gegnern in seinem Weg [Quellwert] Schattenschaden zufügt.\n\nWenn sich das Ziel bei weniger als 35% Gesundheit befindet, beschwört dieser Effekt zwei zusätzliche Phantome mit 25% Effektivität. (1s Abklingzeit)\n\nKy'vezas grausame Werkzeuge (0/2)\nWarpklinge der Leerenschnitterin\nVertrag des Leerenschnitters\n(2) Set : 'Vertrag des Leerenschnitters' beschwört immer zusätzliche Phantome gegen Gegner, die von 'Königinnenmord' betroffen sind.\nVerkaufspreis:", ["unresolvedValues"] = true }
