entries[212491] = { ["name"] = "Süße Eklipse", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (100)\nBenutzen: Stellt im Verlauf von 20 Sek. ( 80357 / 5 * 20) Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt und erhaltet den Effekt 'Süße Eklipse', wodurch jeder in den Schatten getötete Gegner Eure kritische Trefferchance um 3% erhöht.\n\nVerwendbar in Blüte des Lichts und nahen Schlüsselflammengebieten." }
entries[212492] = { ["name"] = "Zwielichtgewürzter Barsch", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (100)\nBenutzen: Stellt im Verlauf von 20 Sek. ( 80357 / 5 * 20) Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, werdet Ihr satt, was Eure Bewegungsgeschwindigkeit um 15% erhöht und den Effekt 'Wasserwandeln' gewährt, während Ihr Euch in Blüte des Lichts und nahen Schlüsselflammengebieten befindet.\n\nVerwendbar in Blüte des Lichts und nahen Schlüsselflammengebieten." }
entries[212493] = { ["name"] = "Seltsamer Wachsklumpen", ["text"] = "Wird beim Aufheben gebunden\n\"Nagerlein und Middels in Gundargaz könnten daran Interesse haben.\"" }
