entries[212514] = { ["name"] = "Blasphemit", ["text"] = "Handwerksmaterial\n\"Dieser hochbegehrte Diamant wird von Alchemisten gewonnen, die sich regelmäßig der Kunst der Thaumaturgie hingeben. Kann im Auktionshaus verkauft und erworben werden.\"\nVerkaufspreis:" }
entries[212517] = { ["name"] = "Fass", ["text"] = "Verbrauchbares\nBenutzen: Völlig von der Rolle! Bewegt Euch für kurze Zeit extrem schnell.\n\nWenn Ihr in andere Einheiten springt oder lauft, explodiert das Fass. Kann über Wasser rollen.\nVerkaufspreis:" }
entries[212518] = { ["name"] = "Phiole der endlosen Drachenschuppen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Ergebt Euch der Ewigkeit, wodurch das Aussehen Eurer anpassbaren Himmelsreittiere zufällig zusammengestellt wird. (1 Stunde Abklingzeit)" }
