entries[212520] = { ["name"] = "Schattenbesudelter Zunderkasten", ["text"] = "Questgegenstand\n\"Zeichen der Hoffnung, das viele der frühen Teilnehmer der Heilsturzexpedition bei sich trugen.\"" }
entries[212522] = { ["name"] = "Kompassrose", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Einer riesigen Hearthstone-Spielkiste entnommen.\"\nWeltereignis:\nHearthstone-Jubiläum" }
entries[212523] = { ["name"] = "Feiner jadegrüner Sonnenschirm", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Zieht für 15 Min. einen schicken jadegrünen Sonnenschirm hervor, der es Euch ermöglicht, bei Eurem nächsten Fall gefahrlos herabzuschweben. (5 Min Abklingzeit)\n\"Perfekt für einen Frühlingsspaziergang.\"" }
entries[212524] = { ["name"] = "Feiner blutroter Sonnenschirm", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Zieht für 15 Min. einen schicken blutroten Sonnenschirm hervor, der es Euch ermöglicht, bei Eurem nächsten Fall gefahrlos herabzuschweben. (5 Min Abklingzeit)\n\"Perfekt für einen ausgedehnten Spaziergang an den Stränden des Jadewalds.\"" }
entries[212525] = { ["name"] = "Feiner ebenholzschwarzer Sonnenschirm", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Zieht für 15 Min. einen schicken ebenholzschwarzen Sonnenschirm hervor, der es Euch ermöglicht, bei Eurem nächsten Fall gefahrlos herabzuschweben. (5 Min Abklingzeit)\n\"Dieser dunkle Baldachin schenkt seinem Träger Schutz vor der Sonne und eine rätselhafte Aura.\"" }
entries[212527] = { ["name"] = "Spinnengeschmiedeter Emitterschlüssel [ENTFERNT]", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Wenn Ihr den Schlüssel habt, könnt Ihr Euch die Pheromone nehmen!\"" }
entries[212528] = { ["name"] = "Zev'kalls Pheromonstrahler", ["text"] = "Questgegenstand\n\"Dieser große Strahler enthält Zev'kalls alchemisierte Pheromone, da er sie nicht selbst herstellen kann.\"" }
entries[212529] = { ["name"] = "Sporenstacheln", ["text"] = "Questgegenstand\nEinzigartig (200)\n\"Wenn die abgerundeten Noppen einmal von den Sporenstacheln entfernt wurden, sind ihre Spitzen schärfer als geschliffener Obsidian oder Diamant. Perfekt geeignet für das Gravieren von Edelsteinen.\"" }
