entries[212599] = { ["name"] = "Edler fliegender Teppich", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Das ist ein Flugreittier.\nBeschwört einen edlen fliegenden Teppich oder gibt ihn wieder frei. Dieses Fortbewegungsmittel passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Magier haben beim Feiern auf dem Nobelgartenfest die gewöhnliche Festdekoration in ein schwebendes Spektakel verwandelt, doch ein verärgerter Druide hat sie gestohlen.\"\nBeute von:\nDaetan Flinkfeder\nFesttag:\nNobelgartenfest" }
