entries[212645] = { ["name"] = "Tonschuppenhornschreiter", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Die Tonschuppenhornschreiter verdanken ihren Namen ihrem tönern-roten Aussehen und durchstreifen die schlammigen Hügel der Ebenen von Ohn'ahra.\"\nBeute von:\nArchive von Azeroth" }
entries[212646] = { ["name"] = "Bestoßene Panzerplatte", ["text"] = "\"Dieses kleine, gestanzte Metallteil wurde einst aneinandergereiht, um daraus eine Rüstung herzustellen. In einigen Löchern finden sich noch Überreste von Fäden.\"\nVerkaufspreis:" }
entries[212647] = { ["name"] = "Lederschuh in Bakargröße", ["text"] = "\"Was noch von diesem Lederschuh übrig ist, ist mit Vlies gefüttert, um nackte Pfoten vor Kälte zu schützen.\"\nVerkaufspreis:" }
entries[212648] = { ["name"] = "Fischgrätennadel", ["text"] = "\"Hergestellt aus den Gräten eines Fisches, den die Tuskarr des Azurblauen Gebirges regelmäßig gegessen haben.\"\nVerkaufspreis:" }
entries[212649] = { ["name"] = "Fetzen eines gesteppten Zelts", ["text"] = "\"Dieses Fragment eines gesteppten Stoffs diente einst als Zeltseite und schirmte all jene im Inneren effektiv gegen die Elemente ab.\"\nVerkaufspreis:" }
entries[212650] = { ["name"] = "Topf mit Tätowiertinte", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Zerbrecht dieses Relikt in eine kleine Menge an mysteriösen Fragmenten.\n\"Die Tinte ist zwar längst getrocknet, aber dieser kleine Tontopf ist übersät mit Kratzern, die von Tätowiernadeln zu stammen scheinen.\"\nVerkaufspreis:" }
