entries[212682] = { ["name"] = "Schlagendes Herz des Wassers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+64 Intelligenz\nAnlegen: Tränkt Euch im Kampf regelmäßig mit besudeltem ursprünglichen Quellwasser, das für 15 Sek. Eure Vielseitigkeit um 38 sowie Eure Bewegungsgeschwindigkeit um 10% verringert.\nWenn Ihr die Unreinheiten des Wassers bannt, kehrt sich der Effekt um und erhöht für 15 Sek. Eure Vielseitigkeit um 161 , Eure Bewegungsgeschwindigkeit um 10% und gewährt allen Verbündeten in der Nähe einen Schild in Höhe von 1087 .\n\"Die Kuriosität pulsiert langsam in Euren Händen, während sich Wasser um Euer Herz legt, sich zusammenzieht und so Euren Herzschlag verlangsamt.\"\nVerkaufspreis:" }
entries[212683] = { ["name"] = "Kugel aus gezacktem Eis", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+64 Beweglichkeit\nBenutzen: Verleiht Euren Fähigkeiten die Macht der Kugel und gewährt 50 Aufladungen von 'Gefrorene Quelle'. Wenn Ihr Schaden verursacht, wird eine Aufladung verbraucht, die 42 zusätzlichen Frostschaden verursacht sowie Gegner mit 'Quellfrost' belegt, um die Bewegungsgeschwindigkeit von Gegnern um 2% pro Stapel zu verringern.\n\nWenn 'Gefrorene Quelle' vollständig verbraucht wurde, erleiden alle Ziele, die mit 'Quellfrost' belegt sind, 141 Frostschaden pro Stapel, aufgeteilt auf alle Ziele in der Nähe. (2 Min Abklingzeit)\nVerkaufspreis:" }
entries[212684] = { ["name"] = "Umbrelskuls gebrochenes Herz", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+64 Intelligenz\nAnlegen: Eure schädlichen Zauber und Fähigkeiten haben eine geringe Chance, die tragischen Arkanmächte anzurufen, damit sie Euer Ziel mit 'Kristallkrankheit' belegen. Betroffene Ziele erleiden [Quellwert] Arkanschaden im Verlauf von 10 Sek., der mit jeder Sekunde ansteigt.\n\nWenn die Gesundheit von Kreaturen (ausgenommen Spielercharaktere und Bosse) unter 5% fällt, während die Kreaturen davon betroffen sind, erstarren sie zu Kristall, sterben und belegen einen Gegner in der Nähe mit 'Kristallkrankheit'. Dies kann bis zu 3-mal auftreten.\nVerkaufspreis:", ["unresolvedValues"] = true }
entries[212685] = { ["name"] = "Foliant der instabilen Macht", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+64 Intelligenz\nAnlegen: Eure schädlichen Zauber haben eine Chance, ein bis drei arkane Illusionen von Euch zu erzeugen. Die arkanen Illusionen kanalisieren 3 Sek. lang, bevor sie 'Arkanbeschuss' auf den Standort Eures Ziels entfesseln und allen Gegnern in diesem Bereich bis zu ( 2487 * 1.1) Arkanschaden zufügen.\nVerkaufspreis:" }
entries[212686] = { ["name"] = "Azurwappenrock der Reiter von Azeroth", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nWappenrock\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen." }
