entries[212749] = { ["name"] = "Explosives Sperrfeuer", ["text"] = "Tüftleredelstein\nWird beim Aufheben gebunden\nEinzigartig\nAnlegen: Eure Fähigkeiten haben eine Chance, ein feuriges Bombardement auf Gegner zu verschießen. Jedes Geschoss verursacht Feuerschaden.\n80 ( 80)\n\"Passt in einen Tüfteleisockel.\"" }
entries[212750] = { ["name"] = "Grimoire des uralten Beobachters", ["text"] = "Wird beim Aufheben gebunden\nKlassen: Hexenmeister\nBenutzen: Schaltet die Anpassungsoptionen für den uralten Beobachter beim Barbier frei.\nVerkaufspreis:" }
entries[212754] = { ["name"] = "Kristallgeschmiedeter Kessel", ["text"] = "Wird an Kriegsmeute gebunden\nHandwerksmaterial\n\"Robust genug, um den ätzendsten Gebräuen zu widerstehen. Kann bei Alchemie- und Schmiedehändlern in Khaz Algar erworben werden, um ihn für Fläschchen und Tränkekessel zu verwenden.\"\nVerkaufspreis:" }
entries[212755] = { ["name"] = "Überbleibseltasche", ["text"] = "Questgegenstand\nEinzigartig (200)\n\"Eine Tasche voller strahlender Überbleibsel.\"" }
entries[212756] = { ["name"] = "Unerbittlicher Schwinger", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+64 [Beweglichkeit oder Stärke]\nAnlegen: Wenn Eure Gesundheit unter 75% fällt, wird für bis zu 15 Sek. die Verteidigungsmatrix aktiviert und absorbiert 50% des erlittenen Schadens, bis zu maximal 16069 Schaden. Während die Matrix aktiv ist, pulsiert der Schwinger alle 1 Sek., um allen Gegnern in der Nähe 177 Feuerschaden zuzufügen. Fügt Zielen über 8 Ziele hinaus verringerten Schaden zu.\n\nDies kann nur alle 1.5 Min. auftreten.\nVerkaufspreis:" }
entries[212757] = { ["name"] = "Granyths robuste Schuppe", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+64 [Beweglichkeit oder Stärke]\nBenutzen: Verringert den erlittenen Schaden 20 Sek. lang um 75% oder bis 22723 Schaden absorbiert wurden. Bei aktivem Schild ist Eure Rüstung um 179 erhöht und wird um weitere 9 erhöht, wenn Ihr einen Treffer erleidet. Bis zu 20-mal stapelbar. Der Schild explodiert, wenn er durchbrochen wird, und verursacht dabei 4970 körperlichen Schaden, der unter allen Gegnern in der Nähe aufgeteilt wird.\n\nDer Schaden erhöht sich für jeden getroffenen Gegner, bis zu einem Maximum von 5 Gegnern. (100ms Abklingzeit) (2 Min Abklingzeit)\nVerkaufspreis:" }
entries[212758] = { ["name"] = "Entflammender Schrecken", ["text"] = "Tüftleredelstein\nWird beim Aufheben gebunden\nEinzigartig\nAnlegen: Eure Fähigkeiten haben eine Chance, zusätzlichen Feuerschaden zu verursachen und Euren Gegner 3 Sek. lang mit Entsetzen zu erfüllen.\n80 ( 80)\n\"Passt in einen Tüfteleisockel.\"" }
entries[212759] = { ["name"] = "Meteoritensturm", ["text"] = "Tüftleredelstein\nWird beim Aufheben gebunden\nEinzigartig\nAnlegen: Eure Fähigkeiten haben eine Chance, einen Meteoritenhagel zu beschwören, der Gegnern in der Nähe Feuerschaden zufügt und sie für 3 Sek. betäubt.\n80 ( 80)\n\"Passt in einen Tüfteleisockel.\"" }
entries[212760] = { ["name"] = "Lauffeuer", ["text"] = "Tüftleredelstein\nWird beim Aufheben gebunden\nEinzigartig\nAnlegen: Eure Angriffe haben eine Chance, Feuerschaden zu verursachen und 'Lauffeuer' auf einen Gegner in der Nähe überspringen zu lassen, das 10 Sek. lang alle 1 Sek. Feuerschaden verursacht.\n\n'Lauffeuer' ist bis zu 3-mal stapelbar und springt auf Gegner in der Nähe über.\n80 ( 80)\n\"Passt in einen Tüfteleisockel.\"" }
entries[212761] = { ["name"] = "Beutel voller Münzen", ["text"] = "\"Jemand muss diesen vor langer, langer Zeit zur sicheren Verwahrung versteckt haben.\"\nVerkaufspreis:" }
entries[212762] = { ["name"] = "Beflecktes Hornsignet", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Zerbrecht dieses Relikt in eine kleine Menge an mysteriösen Fragmenten.\n\"Die Dracthyr scheinen sich die Idee für Hornschmuck von den vor ihnen hier lebenden Drachkin abgeschaut zu haben.\"\nVerkaufspreis:" }
entries[212763] = { ["name"] = "Verdorbener Honigwein", ["text"] = "\"Die Flüssigkeit in dieser Flasche ist milchig und glanzlos. Sie sollte wohl besser nicht mehr getrunken werden, könnte aber dennoch noch wertvolle Einblicke geben.\"\nVerkaufspreis:" }
entries[212764] = { ["name"] = "Fischernetzfragment", ["text"] = "\"Dieses Stück Netz wurde dutzende Male zerfetzt und wieder geflickt, bevor es endgültig eingemottet wurde.\"\nVerkaufspreis:" }
entries[212765] = { ["name"] = "Fischgräten", ["text"] = "\"Übersät mit drakonischen Gebissabdrücken, als ob jemand wirklich jeden Bissen genossen hätte.\"\nVerkaufspreis:" }
entries[212766] = { ["name"] = "Amphorenbruchstück", ["text"] = "\"Wenn man genau hinsieht, erkennt man noch die Abdrücke von mit Klauen versehenen Daumen, die im Ton erhalten geblieben sind.\"\nVerkaufspreis:" }
entries[212767] = { ["name"] = "Zerbrochener Behälter", ["text"] = "\"Der Hals dieses Behälters wurde abgebrochen, um leichter daraus trinken zu können.\"\nVerkaufspreis:" }
entries[212768] = { ["name"] = "Dolch in Niffengröße", ["text"] = "\"Dieser Dolch hat die perfekte Form, um von breiten, klauenbewehrten Händen gehalten zu werden.\"\nVerkaufspreis:" }
entries[212769] = { ["name"] = "Zerfledderter Steckbrief", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Zerbrecht dieses Relikt in eine kleine Menge an mysteriösen Fragmenten.\n\"Die Schrift ist nicht mehr lesbar, aber irgendwer hat das abgebildete Gesicht mit unflätigen Schmierereien besudelt.\"\nVerkaufspreis:" }
entries[212770] = { ["name"] = "Zerschlagene Töpferwaren", ["text"] = "\"Dies war nicht das Werk der Zeit, sondern anscheinend eines oder mehrerer Wurfmessers.\"\nVerkaufspreis:" }
entries[212771] = { ["name"] = "Verkohlte Schneckenhäuser", ["text"] = "\"Die Überreste von Kräutern suggerieren, dass die Schnecken in der Schale über einem Feuer geröstet und anschließend verspeist wurden.\"\nVerkaufspreis:" }
entries[212772] = { ["name"] = "Falsche Silbermünze", ["text"] = "\"Womöglich kam diese verbogene Silbermünze bei betrügerischen Spielen zum Einsatz oder ein sehr enttäuschter Bandit hat sie irgendwo gefunden. Wir werden es wohl nie erfahren.\"\nVerkaufspreis:" }
entries[212773] = { ["name"] = "Rostiges Medaillon", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Zerbrecht dieses Relikt in eine kleine Menge an mysteriösen Fragmenten.\n\"Wurde es gestohlen oder haben ihm die Banditen sentimentalen Wert beigemessen? Was auch immer zutreffen mag, das Innenleben bleibt verschlossen.\"\nVerkaufspreis:" }
entries[212774] = { ["name"] = "Angespitzte Schieferschwingenknochen", ["text"] = "\"Die Abnutzungsspuren an diesen angespitzten Knochen lassen darauf schließen, dass sie einst als Zahnstocher verwendet wurden.\"\nVerkaufspreis:" }
entries[212778] = { ["name"] = "Grimoire des Schreckenstyrannen", ["text"] = "Wird beim Aufheben gebunden\nKlassen: Hexenmeister\nBenutzen: Schaltet die Anpassungsoptionen für den Schreckenstyrannen beim Barbier frei.\nVerkaufspreis:" }
entries[212779] = { ["name"] = "Grimoire des Blutrauschtyrannen", ["text"] = "Wird beim Aufheben gebunden\nKlassen: Hexenmeister\nBenutzen: Schaltet die Anpassungsoptionen für den Blutrauschtyrannen beim Barbier frei.\nVerkaufspreis:" }
entries[212780] = { ["name"] = "Grimoire des Teufelsschlägertyrannen", ["text"] = "Wird beim Aufheben gebunden\nKlassen: Hexenmeister\nBenutzen: Schaltet die Anpassungsoptionen für den Teufelsschlägertyrannen beim Barbier frei.\nVerkaufspreis:" }
entries[212781] = { ["name"] = "Formulierter Mut", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Trinkt dies, um Eure Konzentration auf Eure Experimente zu schärfen, damit Ihr 10 Min. lang Eure Jagd nach alchemistischer Größe fortsetzen könnt, ohne Rücksicht auf Verluste. (10 Sek. Abklingzeit)\nBenötigt Alchemie von Khaz Algar\n(1)\nVerkaufspreis:" }
entries[212782] = { ["name"] = "Schlecht erhaltenes Relikt", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Zerbrecht dieses Relikt in eine kleine Menge an mysteriösen Fragmenten.\n\"Die Archivare können durch dieses Relikt vielleicht noch etwas lernen, aber vermutlich ist es ertragreicher, es einfach zu verkaufen.\"\nVerkaufspreis:" }
entries[212783] = { ["name"] = "Grimoire des Netherwandlertyrannen", ["text"] = "Wird beim Aufheben gebunden\nKlassen: Hexenmeister\nBenutzen: Schaltet die Anpassungsoptionen für den Netherwandlertyrannen beim Barbier frei.\nVerkaufspreis:" }
entries[212784] = { ["name"] = "Zerstörtes Relikt", ["text"] = "\"Dieses Relikt hätte für die Archivare womöglich von großem Wert sein können, doch der Zahn der Zeit hat es fast restlos zerstört.\"\nVerkaufspreis:" }
entries[212785] = { ["name"] = "Helm des Starken", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nKopf Kosmetisch\n\"In die Rückseite wurde \"Olaf\" geritzt.\"\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[212786] = { ["name"] = "Herziges Entchen", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört und wieder freigibt.\nMit Rechtsklick dieses Haustier beschwören oder wieder freigeben.\n80 ( 80)" }
entries[212787] = { ["name"] = "Handschuhe der violetten Gala", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nHände Kosmetisch\n\"Diese hauchzarten Handschuhe sind glamouröse Gewandung für eine gewaltige Gala.\"\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[212788] = { ["name"] = "Smaragdgrünes Gazegewand", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nBrust Kosmetisch\n\"Perfekt für ein Gartenfest im Frühling.\"\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[212789] = { ["name"] = "Jadespaltbeil des Champions", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nZweihändig Stangenwaffe\n1 - 3 Schaden Geschwindigkeit 3.60\n(0.6 Schaden pro Sekunde)\n\"3000 Jahre lang beherrschte das Mogureich Pandaria. Dieses Relikt ist Zeuge seiner Grausamkeit.\"\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
entries[212790] = { ["name"] = "Kodex der klassischen Beschwörungen", ["text"] = "Kosmetisch\nWird an Kriegsmeute gebunden\nIn Schildhand geführt\n\"Zu den Themen gehören Manaedelsteine, Wasser und Nahrung bis hin zu Zimtschnecken.\"\nBenutzen: Diese Vorlage zur Kriegsmeutensammlung hinzufügen.\nVerkaufspreis:" }
